"""Panel HTML autónomo: funciona sin servidor y sin conexión."""
import base64
import json
from pathlib import Path


def crear_panel(tabla, detalles, resumen, indicadores, rutas):
    from analisis import BASE, ETIQUETAS, SITIO, FECHA
    datos=json.loads(tabla.to_json(orient='records'))
    evaluaciones=json.loads(detalles.to_json(orient='records'))
    figuras=''.join(f'<figure><img alt="{p.stem}" src="data:image/png;base64,{base64.b64encode(p.read_bytes()).decode()}"></figure>' for p in rutas)
    plantilla=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AquaLytics · Calidad del agua</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6f7;color:#152e38;font:15px Arial,sans-serif}header{background:#123d50;color:white;padding:32px max(5vw,20px)}h1{margin:0 0 8px;font-size:34px}main{max-width:1250px;margin:auto;padding:24px}h2{font-size:22px}.aviso{background:#fff2d6;border-left:5px solid #af7116;padding:16px;line-height:1.5}.controles,.tarjetas{display:flex;gap:15px;flex-wrap:wrap;margin:20px 0}.controles label{display:flex;flex-direction:column;gap:6px;flex:1;min-width:150px}select,input,button{padding:10px;border:1px solid #b1c4cc;border-radius:5px;background:white;font:inherit}button{cursor:pointer;background:#17546a;color:white}.tarjeta{background:white;flex:1;min-width:175px;padding:20px;border-radius:8px}.tarjeta strong{display:block;font-size:30px;margin:6px 0}.panel{background:white;padding:20px;border-radius:8px;margin-bottom:20px}.tabla{overflow:auto;max-height:520px}table{border-collapse:collapse;width:100%;white-space:nowrap}th,td{padding:10px;border-bottom:1px solid #dde5e8;text-align:left;font-size:13px}th{position:sticky;top:0;background:#e7eff2}.malo{color:#ac3629}.nota{color:#526872;font-size:13px;line-height:1.6}figure{background:white;padding:16px;margin:20px 0}img{width:100%;height:auto}svg{width:100%;height:auto}summary{cursor:pointer;padding:15px;font-weight:bold}a{color:#17546a}footer{padding:20px 0}#vacio{display:none}button:focus,select:focus,input:focus{outline:3px solid #74b4ca}@media print{.controles,button{display:none}.tabla{max-height:none}body{background:white}}</style>
<header><h1>AquaLytics</h1><div>Evaluación descriptiva de la calidad del agua · Datos de 2020 a 2024</div></header><main>
<p class="aviso"><b>Potabilidad no determinada.</b> Evaluación parcial de siete parámetros frente a referencias panameñas de 2021. Las fuentes son USGS y NPS de Estados Unidos. Faltan análisis microbiológicos y cloro residual; las aguas de origen no equivalen a agua potable tratada.</p>
<div class="controles"><label>Organismo<select id="org"></select></label><label>Estación<select id="sitio"></select></label><label>Desde<input id="desde" type="date"></label><label>Hasta<input id="hasta" type="date"></label><label>Estado<select id="estado"><option value="">Todos</option><option>Con excedencias</option><option>Sin excedencias observadas</option><option>Sin datos evaluables</option></select></label><label>Calidad del resultado<select id="calidad"><option value="todos">Todos los resultados</option><option value="confirmados">Sin preliminares ni estimados</option></select></label></div>
<div class="tarjetas" id="tarjetas"></div><p id="vacio">No hay actividades para esta selección. Cambia los filtros.</p>
<section class="panel"><h2>Excedencias en la selección</h2><p class="nota">Porcentaje entre actividades con medición válida de cada parámetro. Cada barra muestra excedencias / evaluables. Una actividad puede incluir más de un resultado; cualquier excedencia activa la alerta.</p><div id="barras"></div></section>
<section class="panel"><h2>Explorar mediciones</h2><label>Parámetro <select id="parametro"></select></label><p class="nota">Medianas por actividad. Los puntos pertenecen a estaciones y medios diferentes; no representan una sola trayectoria temporal.</p><div id="serie"></div></section>
<section class="panel"><h2>Actividades evaluadas</h2><button id="descargar">Descargar selección CSV</button><p class="nota">Vista de hasta 500 filas. La descarga incluye todas las filas filtradas. Cobertura = parámetros disponibles / 7. Los valores en pantalla son medianas; las alertas consideran las observaciones originales.</p><div class="tabla" id="tabla"></div></section>
<details class="panel"><summary>Método y límites utilizados</summary><p>No se aplicó regresión lineal. Se usan reglas deterministas, estadísticas descriptivas, intervalos intercuartílicos y Spearman con al menos 20 pares. No se imputaron faltantes ni se eliminaron valores extremos válidos. Los controles de calidad se conservaron en otro archivo.</p><p>Referencias: pH 6.5–8.5; conductividad ≤850 µS/cm; cloruros ≤250 mg/L; fluoruros ≤0.8 mg/L; sulfatos ≤250 mg/L; dureza ≤200 mg/L CaCO3; SDT ≤500 mg/L. Los extremos del intervalo son inclusivos.</p><p>Los resultados de fracción disuelta se comparan de forma orientativa: no demuestran cumplimiento de una medición total. Se conserva la fracción en el detalle. La turbidez FNU y NTRU se mantiene separada y no se compara automáticamente con UNT. No se convierten porcentajes de saturación a mg/L ni toneladas/acre-pie a mg/L; se utilizan las mediciones directas compatibles.</p><p>La vista de calidad filtra actividades enteras que contienen datos preliminares o estimados. El archivo de sensibilidad vuelve a calcular la evaluación por observación y puede conservar datos confirmados de una actividad mixta.</p><p><a href="https://asep.gob.pa/wp-content/uploads/agua/legislacion/dgnti_21-2019_mod.pdf">Resolución 122 de 2021 · página 2</a> · <a href="https://www.who.int/publications/i/item/9789240121225">Guías de la OMS</a></p></details>
<details><summary>Ocho visualizaciones del conjunto completo</summary>__FIGURAS__</details>
<footer class="nota">Equipo: Ricardo Vasquez · Mario Aranda · Juan Aranda. Samsung Innovation Campus. Panel autónomo generado con Python; no requiere conexión.</footer>
</main><script>
const datos=__DATOS__, detalles=__DETALLES__, etiquetas=__ETIQUETAS__;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function opciones(id,valores){$(id).innerHTML='<option value="">Todos</option>'+valores.map(v=>'<option>'+esc(v)+'</option>').join('')}
opciones('org',[...new Set(datos.map(d=>d.OrganizationIdentifier))].sort());
opciones('sitio',[...new Set(datos.map(d=>d.MonitoringLocationIdentifier))].sort());
$('parametro').innerHTML=Object.entries(etiquetas).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
const fechas=datos.map(d=>d.ActivityStartDate).sort();$('desde').value=fechas[0];$('hasta').value=fechas.at(-1);
let seleccion=[];
function actualizar(){
 seleccion=datos.filter(d=>(!$('org').value||d.OrganizationIdentifier===$('org').value)&&(!$('sitio').value||d.MonitoringLocationIdentifier===$('sitio').value)&&(!$('desde').value||d.ActivityStartDate>=$('desde').value)&&(!$('hasta').value||d.ActivityStartDate<=$('hasta').value)&&(!$('estado').value||d.estado===$('estado').value)&&($('calidad').value==='todos'||(!d.preliminar&&!d.estimado)));
 const n=seleccion.length,alertas=seleccion.filter(d=>d.parametros_fuera>0).length,cob=n?seleccion.reduce((a,d)=>a+d.cobertura_pct,0)/n:0;
 $('tarjetas').innerHTML=[['Actividades',n],['Con excedencias',alertas],['Estaciones',new Set(seleccion.map(d=>d.MonitoringLocationIdentifier)).size],['Cobertura media',cob.toFixed(1)+'%']].map(([t,v])=>`<div class="tarjeta">${t}<strong>${v}</strong></div>`).join('');$('vacio').style.display=n?'none':'block';
 const claves=new Set(seleccion.map(d=>d.OrganizationIdentifier+'|'+d.ActivityIdentifier));
 const ev=detalles.filter(d=>claves.has(d.OrganizationIdentifier+'|'+d.ActivityIdentifier)),parametros=[...new Set(detalles.map(d=>d.parametro))];
 $('barras').innerHTML='<svg viewBox="0 0 1050 350" role="img" aria-label="Excedencias por parámetro">'+parametros.map((p,i)=>{const g=ev.filter(d=>d.parametro===p&&d.n_mediciones>0),f=g.filter(d=>d.estado==='Fuera de referencia').length,v=g.length?100*f/g.length:0,y=20+i*44;return `<text x="0" y="${y+17}" font-size="15">${esc(etiquetas[p])}</text><rect x="260" y="${y}" width="600" height="26" fill="#edf2f4"/><rect x="260" y="${y}" width="${6*v}" height="26" fill="#af4f3f"/><text x="875" y="${y+17}" font-size="14">${g.length?v.toFixed(1)+'%':'Sin datos'} (${f}/${g.length})</text>`}).join('')+'</svg>';
 const p=$('parametro').value, puntos=seleccion.filter(d=>d[p]!==null).sort((a,b)=>a.ActivityStartDate.localeCompare(b.ActivityStartDate));
 if(puntos.length){let lo=Math.min(...puntos.map(d=>d[p])),hi=Math.max(...puntos.map(d=>d[p]));if(hi===lo)hi=lo+1;const x0=Date.parse(puntos[0].ActivityStartDate),x1=Date.parse(puntos.at(-1).ActivityStartDate),rango=x1-x0||1;
 $('serie').innerHTML=`<svg viewBox="0 0 1050 310" role="img" aria-label="Mediciones del parámetro seleccionado"><path d="M65 15 V265 H1020" stroke="#829da8" fill="none"/><text x="5" y="25">${hi.toFixed(2)}</text><text x="5" y="265">${lo.toFixed(2)}</text><text x="65" y="295">${puntos[0].ActivityStartDate}</text><text x="900" y="295">${puntos.at(-1).ActivityStartDate}</text>`+puntos.map(d=>`<circle cx="${70+940*(Date.parse(d.ActivityStartDate)-x0)/rango}" cy="${260-235*(d[p]-lo)/(hi-lo)}" r="4" fill="#236c84" opacity=".65"><title>${esc(d.MonitoringLocationIdentifier)} · ${d.ActivityStartDate} · ${d[p]}</title></circle>`).join('')+'</svg>';
 }else $('serie').textContent='Sin mediciones para el parámetro seleccionado.';
 const columnas=['MonitoringLocationIdentifier','ActivityStartDate','ActivityIdentifier',p,'estado','parametros_evaluados','parametros_fuera','cobertura_pct','potabilidad'];
 $('tabla').innerHTML='<table><thead><tr>'+columnas.map(c=>'<th>'+esc(etiquetas[c]||c)+'</th>').join('')+'</tr></thead><tbody>'+seleccion.slice(0,500).map(d=>'<tr>'+columnas.map(c=>'<td class="'+(c==='estado'&&d.parametros_fuera?'malo':'')+'">'+esc(typeof d[c]==='number'?Number(d[c].toFixed(3)):(d[c]??'Sin dato'))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
}
for(const id of ['org','sitio','desde','hasta','estado','calidad','parametro'])$(id).addEventListener('change',actualizar);
$('descargar').onclick=()=>{const cols=Object.keys(datos[0]),q=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv='\ufeff'+[cols.map(q).join(','),...seleccion.map(d=>cols.map(c=>q(d[c])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='aqualytics_seleccion.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
actualizar();
</script></html>'''
    plantilla=plantilla.replace('__DATOS__',json.dumps(datos,ensure_ascii=False)).replace('__DETALLES__',json.dumps(evaluaciones,ensure_ascii=False)).replace('__ETIQUETAS__',json.dumps(ETIQUETAS,ensure_ascii=False)).replace('__FIGURAS__',figuras)
    (BASE/'resultados/Panel_AquaLytics.html').write_text(plantilla,encoding='utf-8')
